ANNOTATIONS = [
    (21, 'before', r'''inputSchema 两参数：query（「select:工具名」直选或关键词搜索）、max_results（默认 5）。max_results 有默认值——模型不传也能用，schema 层的 .default(5) 比 prompt 里写「建议 5 个」可靠。'''),
    (37, 'before', r'''outputSchema：matches（工具名数组——注意是名字不是完整 schema，真正的 schema 由 mapToolResult 以 tool_reference 块下发）+ query 回显 + total_deferred_tools（让模型知道自己漏了多少）+ pending_mcp_servers（还在连接的服务器，解释「为什么搜不到」）。'''),
    (49, 'after', r'''模块级缓存变量：记住「上次见到的 deferred 工具集合」。工具集会随 MCP 连接/断开、特性开关变化——集合一变，描述缓存全部作废。'''),
    (55, 'before', r'''getDeferredToolsCacheKey：把工具名排序后拼接成缓存键。排序保证顺序无关——tools 数组的枚举顺序不该影响缓存命中。'''),
    (66, 'before', r'''getToolDescriptionMemoized：按工具名 memoize 描述生成。注意 resolver 的第二个参数 tools 不在缓存键里（memoize 只按 toolName）——描述只取决于工具本身，tools 数组只是调用 prompt() 需要的上下文；集合变化由 maybeInvalidateCache 显式清缓存，不依赖键设计。prompt() 调用时现造一个 default 模式的最小权限上下文——搜索只需要文本，不需要真实权限状态。'''),
    (91, 'before', r'''maybeInvalidateCache：每次搜索前比对缓存键，变了就清 lodash memoize 缓存并更新键。调试日志说明清缓存是低频事件（只在工具集变化时）——如果它高频出现，说明有地方在反复重建工具列表。'''),
    (102, 'before', r'''clearToolSearchDescriptionCache 是导出的手动清除入口——供会话重置、MCP 重连等外部事件调用，不依赖下一次搜索的惰性校验。'''),
    (110, 'before', r'''buildSearchResult：统一构造返回结构。pending_mcp_servers 只在非空时 Spread 进结果——可选字段不出空数组，schema 消费方少一层判空。'''),
    (132, 'before', r'''parseToolName：把工具名拆成可搜索的词根。MCP 工具（mcp__server__action）拆成 server+action 词根；普通工具按 CamelCase 与下划线拆。isMcp 标记后面用于加权——服务器名匹配比动作词匹配更值得信任。'''),
    (167, 'before', r'''compileTermPatterns：一次搜索把词根预编译成词边界正则。注释点明性能动机——否则会是 工具数×词数×2 次的正则编译；Map 去重保证同词只编译一次。escapeRegExp 防用户查询里的正则元字符穿洞。'''),
    (186, 'before', r'''searchToolsWithKeywords 主流程。文档注释列出模型的三种典型查询形态：知道集成商时搜服务器名（slack/github）、找功能时搜动作词（read/list/create）、找特定工具时搜专名（notebook/shell/kill）——评分权重就是按这个使用分布调的。'''),
    (202, 'before', r'''精确名匹配快速通道：查询整个就是个工具名（大小写不敏感）时直接返回。注释说明这是给「压缩后/子代理里模型直接用裸工具名」的场景兜底——先查 deferred 再查全量，选中已加载工具是无害 no-op，让模型不用重试。这是对模型习惯的顺应而非纠正。'''),
    (208, 'before', r'''mcp__ 前缀特判：模型按服务器名带前缀搜索时，直接前缀过滤取前 N 个。比词根评分更快也更准——服务器名是精确标识，不需要模糊匹配。'''),
    (218, 'after', r'''查询分词：空白切分。+前缀词（如「+slack send」的 +slack）在下一步被提为必选词——「+」是给模型的微型查询语法，比自然语言「必须包含 slack」可靠。'''),
    (220, 'after', r'''必选/可选分区：+前缀进 requiredTerms，其余进 optionalTerms。有必选词时先用 ALL 语义预过滤候选（名称词根或描述命中每一个必选词），再对候选评分——两阶段设计避免「高分但缺关键服务器」的错配排前面。'''),
    (304, 'before', r'''buildTool 主结构。三个布尔全为真：可并发（纯查询）、只读（不改状态）、但 isEnabled 走 isToolSearchEnabledOptimistic——乐观启用，即使远程开关还没刷新到也先用默认值，避免功能「时灵时不灵」。'''),
    (328, 'before', r'''call() 从 options.tools 里过滤出 deferred 集合，先做缓存校验（工具集可能刚变）。两个内部辅助函数——getPendingServerNames（从 AppState.mcp.clients 找 pending 状态的）与 logSearchOutcome（tengu_tool_search_outcome 遥测：查询类型、命中数、总数、是否有结果）——都定义在 call 作用域内，随调用创建随调用销毁，不污染模块。'''),
    (363, 'after', r'''select: 直选支持逗号分隔多选（select:A,B,C）。逐个查找时同样先 deferred 后全量——请求一个已加载工具返回它，模型不会因为「已经加载过」而吃到错误。部分命中时 found 照常返回、missing 只记 debug 日志——不因一个坏名字废掉整批。'''),
    (409, 'before', r'''关键词搜索回落：select 不命中（或不是 select 形式）时走评分搜索。零结果时附带 pending_mcp_servers——「搜不到」的常见原因是服务器还在连，这个字段把猜测变成确定信息。'''),
    (444, 'before', r'''mapToolResult 把 matches 转成 tool_reference 块数组——这是本工具与普通工具的本质区别：它返回的不是文本而是「工具定义句柄」，客户端（1P/Foundry）据此把完整 schema 展开进上下文。注释明说 Bedrock/Vertex 可能不支持客户端展开——跨提供商兼容是这个设计的隐藏成本，as unknown as 强转正是为兜底格式差异。'''),
    (448, 'after', r'''零命中文案带条件后缀：有 pending 服务器时明说「它们还在连接，稍后再试」——把「搜索失败」重新框定为「时机未到」，模型学会等待而不是换查询词乱试。'''),
]
